{
  "cases": [
    {
      "id": "C1",
      "probes": [
        {
          "id": "repeat_test",
          "label": "Not established",
          "quote": "The report does not say whether runs were repeated.",
          "reason": "Repeat testing is undocumented; this does not establish whether it occurred."
        },
        {
          "id": "stable",
          "label": "Not established",
          "quote": "70% in one reported run",
          "reason": "One reported score cannot establish consistency across repeated runs."
        }
      ],
      "instrument_review": "The puzzle count, scoring rule, and narrow intended use are stated. The score describes the reported run; repeatability, puzzle selection, and conditions needed for fair system comparisons remain insufficiently documented."
    },
    {
      "id": "C2",
      "probes": [
        {
          "id": "repeat_test",
          "label": "Contradicted",
          "quote": "ran the evaluation exactly once and did not repeat it",
          "reason": "The passage explicitly rules out repeated-run testing."
        },
        {
          "id": "stable",
          "label": "Not established",
          "quote": "ran the evaluation exactly once",
          "reason": "A single evaluation supplies no evidence of repeated-run stability or instability."
        }
      ],
      "instrument_review": "Scoring and the narrow intended use are clear. The documented absence of repeat testing limits consistency claims. The reported 70% describes one run; construction details and fair comparison conditions are not fully supplied."
    },
    {
      "id": "C3",
      "probes": [
        {
          "id": "repeat_test",
          "label": "Supported",
          "quote": "repeated the evaluation ten times with the same system, inputs, instructions, resources, and settings",
          "reason": "Repeated evaluations under the specified unchanged conditions are explicitly documented."
        },
        {
          "id": "stable",
          "label": "Supported",
          "quote": "Scores ranged from 69% to 71%.",
          "reason": "The reported range meets the stated stability criterion of at most two percentage points."
        }
      ],
      "instrument_review": "Repeated-run consistency is supported under the report's explicit criterion and controlled conditions. This supports interpretation for these puzzles and settings; it does not establish consistency on other puzzles or under changed conditions. Puzzle selection and between-system comparison procedures remain unspecified."
    },
    {
      "id": "C4",
      "probes": [
        {
          "id": "repeat_test",
          "label": "Supported",
          "quote": "repeated the evaluation ten times with the same system, inputs, instructions, resources, and settings",
          "reason": "The passage explicitly documents repeated evaluations under unchanged conditions."
        },
        {
          "id": "stable",
          "label": "Contradicted",
          "quote": "Scores ranged from 20% to 90%.",
          "reason": "The observed range exceeds the report's maximum two-percentage-point stability criterion."
        }
      ],
      "instrument_review": "Repeat testing documents a consistency problem under the stated criterion. The single 70% score cannot adequately convey the reported variability. Comparisons should account for this variability; its cause and puzzle selection details remain unknown."
    },
    {
      "id": "C5",
      "probes": [
        {
          "id": "repeat_test",
          "label": "Not established",
          "quote": "The report does not say whether runs were repeated.",
          "reason": "Installation instructions do not document repeated-run testing."
        },
        {
          "id": "stable",
          "label": "Not established",
          "quote": "They report no additional evaluation results.",
          "reason": "No repeated-run findings are supplied to support score stability."
        }
      ],
      "instrument_review": "Installation guidance documents setup steps, but adds no evidence about consistency or comparison quality. Exact-grid scoring and the narrow intended use are stated; repeatability, puzzle selection, and fair comparison conditions remain insufficiently documented."
    },
    {
      "id": "C6",
      "probes": [
        {
          "id": "narrow",
          "label": "Supported",
          "quote": "System A solves 80 puzzles and system B solves 60",
          "reason": "A has the higher observed result on the evaluated grid puzzles."
        },
        {
          "id": "broad",
          "label": "Not established",
          "quote": "Only grid puzzles were tested; no findings about other tasks are supplied.",
          "reason": "The evidence does not establish a comparison of general intelligence across domains."
        }
      ],
      "instrument_review": "The observed comparison fits the stated narrow use, with exact-grid scoring and fixed instructions. Repeated-run consistency, puzzle selection, and equality of other evaluation conditions are unspecified. Broader ability claims exceed the supplied evidence."
    },
    {
      "id": "C7",
      "probes": [
        {
          "id": "narrow",
          "label": "Supported",
          "quote": "System A solves 80 puzzles and system B solves 60",
          "reason": "The reported evaluation shows better grid-puzzle performance for A."
        },
        {
          "id": "broad",
          "label": "Not established",
          "quote": "Only grid puzzles were tested; no findings about other tasks are supplied.",
          "reason": "The broad intended use does not supply evidence of greater intelligence across domains."
        }
      ],
      "instrument_review": "The intended selection use exceeds the demonstrated scope: grid-puzzle results alone do not establish general intelligence across domains. Scoring and instructions are specified, but repeatability, broader task coverage, and equality of other comparison conditions remain undocumented."
    },
    {
      "id": "C8",
      "probes": [
        {
          "id": "before",
          "label": "Not established",
          "quote": "Initially, only test scores were available.",
          "reason": "The initial scores alone provide no demonstrated comparison of effects on actual workshop decisions."
        },
        {
          "id": "after",
          "label": "Supported",
          "quote": "With A, 90% of decisions were correct; with B, 70%.",
          "reason": "The randomized trial supports better correctness with A in the studied conditions; the reported difference interval is entirely positive."
        },
        {
          "id": "safety",
          "label": "Not established",
          "quote": "Time and safety outcomes were not measured.",
          "reason": "Correctness findings alone do not establish an improvement in unmeasured safety outcomes."
        }
      ],
      "instrument_review": "The preregistered randomized comparison, new cases, blinded correctness checks, and reported uncertainty support the intended workshop-specific correctness decision. Evidence is limited to one workshop and the studied conditions. Time, safety, broader applicability, and details of the initial test construction and scoring remain unestablished."
    }
  ],
  "closing_note": "No instructions were unclear. Missing evidence was distinguished from explicit contradiction; an intended use was not treated as evidence that the use is justified."
}
